/** These files are generated once and shipped with the built-in books. */
const PAGE_COUNTS: Record<string, number> = {
  "noahs-ark": 6,
  "three-little-pigs": 5,
  "tortoise-and-hare": 5,
  "little-red-riding-hood": 5,
