}

export function isStandardArtUrl(url: string): boolean {
  return Object.entries(PAGE_COUNTS).some(([id, count]) =>
    Array.from({ length: count }, (_, index) => `/story-art/${id}/beat-${index}.jpg`).includes(url));
}

